"use client";
/* Peeper, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Peeper(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("peeper"); }, []);
  return React.createElement("piix-pal", { "pal": "peeper", ...piixAttrs(props) });
}

export default Peeper;
